       IF NOT FOUND THEN
         RAISE EXCEPTION 'Referenced folder % does not exist', NEW.folder_id USING ERRCODE = 'foreign_key_violation';
       END IF;
       IF NEW.project_id IS DISTINCT FROM folder_proj THEN
         RAISE EXCEPTION 'Generation scope mismatch: generation project_id (%) does not match folder project_id (%)',
           NEW.project_id, folder_proj USING ERRCODE = 'check_violation';
       END IF;
     END IF;
     RETURN NEW;
   END;
   $$ LANGUAGE plpgsql","DROP TRIGGER IF EXISTS trg_check_generation_scope ON generations","CREATE CONSTRAINT TRIGGER trg_check_generation_scope AFTER INSERT OR UPDATE OF folder_id, project_id ON generations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_generation_scope_integrity()","CREATE TABLE IF NOT EXISTS organization_idempotency_keys (
