      ALTER TABLE generation_naming ADD CONSTRAINT generation_naming_generation_id_fkey
        FOREIGN KEY (generation_id) REFERENCES generations(id) ON DELETE CASCADE;
    END IF;
  END $$;","CREATE OR REPLACE FUNCTION check_generation_naming_scope_integrity()
   RETURNS TRIGGER AS $$
   DECLARE
     gen_folder UUID;
     gen_project UUID;
     expected_ns TEXT;
     allocated_seq BIGINT;
     now_ts BIGINT;
   BEGIN
     IF TG_TABLE_NAME = 'generation_naming' THEN
       SELECT folder_id, project_id INTO gen_folder, gen_project
       FROM generations WHERE id = NEW.generation_id;
       IF NOT FOUND THEN
         RETURN NEW;
       END IF;

       IF gen_folder IS NOT NULL THEN
         expected_ns := 'folder:' || gen_folder::text;
       ELSIF gen_project IS NOT NULL THEN
         expected_ns := 'project_unsorted:' || gen_project::text;
       ELSE
         expected_ns := 'global_unsorted';
       END IF;

       IF NEW.namespace IS DISTINCT FROM expected_ns THEN
         RAISE EXCEPTION 'Naming namespace mismatch: namespace (%) does not match generation (%) location (%)',
           NEW.namespace, NEW.generation_id, expected_ns USING ERRCODE = 'check_violation';
       END IF;
       RETURN NEW;

     ELSIF TG_TABLE_NAME = 'generations' THEN
       now_ts := ROUND(EXTRACT(EPOCH FROM clock_timestamp()) * 1000)::bigint;

       IF NEW.folder_id IS NOT NULL THEN
         expected_ns := 'folder:' || NEW.folder_id::text;
       ELSIF NEW.project_id IS NOT NULL THEN
         expected_ns := 'project_unsorted:' || NEW.project_id::text;
       ELSE
         expected_ns := 'global_unsorted';
       END IF;

       IF TG_OP = 'INSERT' THEN
         -- Auto-assign naming row if omitted (supports old application inserts)
         IF NOT EXISTS (SELECT 1 FROM generation_naming WHERE generation_id = NEW.id) THEN
           INSERT INTO naming_counters (namespace, next_sequence, updated_at)
           VALUES (expected_ns, 2, now_ts)
           ON CONFLICT (namespace) DO UPDATE SET
             next_sequence = naming_counters.next_sequence + 1,
             updated_at = EXCLUDED.updated_at
           RETURNING next_sequence - 1 INTO allocated_seq;

           INSERT INTO generation_naming (generation_id, namespace, sequence, assigned_at)
           VALUES (NEW.id, expected_ns, allocated_seq, now_ts)
           ON CONFLICT (generation_id) DO NOTHING;
         END IF;
         RETURN NEW;

       ELSIF TG_OP = 'UPDATE' AND (NEW.folder_id IS DISTINCT FROM OLD.folder_id OR NEW.project_id IS DISTINCT FROM OLD.project_id) THEN
         -- Auto-reassign naming row if omitted or mismatched (supports old application moves, code rollback, and direct SQL)
         IF NOT EXISTS (SELECT 1 FROM generation_naming WHERE generation_id = NEW.id) THEN
           INSERT INTO naming_counters (namespace, next_sequence, updated_at)
           VALUES (expected_ns, 2, now_ts)
           ON CONFLICT (namespace) DO UPDATE SET
             next_sequence = naming_counters.next_sequence + 1,
             updated_at = EXCLUDED.updated_at
           RETURNING next_sequence - 1 INTO allocated_seq;

           INSERT INTO generation_naming (generation_id, namespace, sequence, assigned_at)
           VALUES (NEW.id, expected_ns, allocated_seq, now_ts)
           ON CONFLICT (generation_id) DO NOTHING;
         ELSIF EXISTS (
           SELECT 1 FROM generation_naming
           WHERE generation_id = NEW.id AND namespace IS DISTINCT FROM expected_ns
         ) THEN
           INSERT INTO naming_counters (namespace, next_sequence, updated_at)
           VALUES (expected_ns, 2, now_ts)
           ON CONFLICT (namespace) DO UPDATE SET
             next_sequence = naming_counters.next_sequence + 1,
             updated_at = EXCLUDED.updated_at
           RETURNING next_sequence - 1 INTO allocated_seq;

           UPDATE generation_naming
           SET namespace = expected_ns, sequence = allocated_seq, assigned_at = now_ts
           WHERE generation_id = NEW.id;
         END IF;
       END IF;
       RETURN NEW;
     END IF;

     RETURN NEW;
   END;
   $$ LANGUAGE plpgsql","DROP TRIGGER IF EXISTS trg_check_generation_naming_scope ON generation_naming","CREATE CONSTRAINT TRIGGER trg_check_generation_naming_scope
   AFTER INSERT OR UPDATE ON generation_naming
   DEFERRABLE INITIALLY DEFERRED
   FOR EACH ROW
   EXECUTE FUNCTION check_generation_naming_scope_integrity()","DROP TRIGGER IF EXISTS trg_check_generation_location_naming ON generations","CREATE CONSTRAINT TRIGGER trg_check_generation_location_naming
   AFTER INSERT OR UPDATE OF folder_id, project_id ON generations
   DEFERRABLE INITIALLY DEFERRED
   FOR EACH ROW
   EXECUTE FUNCTION check_generation_naming_scope_integrity()","WITH unassigned AS (
    SELECT
      g.id AS generation_id,
      CASE
        WHEN g.folder_id IS NOT NULL THEN 'folder:' || g.folder_id::text
        WHEN g.project_id IS NOT NULL THEN 'project_unsorted:' || g.project_id::text
        ELSE 'global_unsorted'
      END AS namespace,
      g.created_at
    FROM generations g
    LEFT JOIN generation_naming gn ON g.id = gn.generation_id
    WHERE gn.generation_id IS NULL
  ),
  allocated AS (
    SELECT
      u.generation_id,
      u.namespace,
      COALESCE(c.max_seq, 0) + ROW_NUMBER() OVER (
        PARTITION BY u.namespace
        ORDER BY u.created_at ASC, u.generation_id ASC
      ) AS sequence,
      ROUND(EXTRACT(EPOCH FROM NOW()) * 1000)::bigint AS assigned_at
    FROM unassigned u
    LEFT JOIN (
      SELECT namespace, MAX(sequence) AS max_seq
      FROM generation_naming
      GROUP BY namespace
    ) c ON u.namespace = c.namespace
  )
  INSERT INTO generation_naming (generation_id, namespace, sequence, assigned_at)
  SELECT generation_id, namespace, sequence, assigned_at
  FROM allocated
  ON CONFLICT (generation_id) DO NOTHING","INSERT INTO naming_counters (namespace, next_sequence, updated_at)
   SELECT
     namespace,
     COALESCE(MAX(sequence), 0) + 1 AS next_sequence,
     ROUND(EXTRACT(EPOCH FROM NOW()) * 1000)::bigint AS updated_at
   FROM generation_naming
   GROUP BY namespace
   ON CONFLICT (namespace) DO UPDATE
   SET next_sequence = GREATEST(naming_counters.next_sequence, EXCLUDED.next_sequence),
       updated_at = EXCLUDED.updated_at","INSERT INTO naming_counters (namespace, next_sequence, updated_at)
   SELECT 'folder:' || id::text, 1, ROUND(EXTRACT(EPOCH FROM NOW()) * 1000)::bigint
   FROM folders
   ON CONFLICT (namespace) DO NOTHING","INSERT INTO naming_counters (namespace, next_sequence, updated_at)
   SELECT 'project_unsorted:' || id::text, 1, ROUND(EXTRACT(EPOCH FROM NOW()) * 1000)::bigint
   FROM projects
   ON CONFLICT (namespace) DO NOTHING","INSERT INTO naming_counters (namespace, next_sequence, updated_at)
   VALUES ('global_unsorted', 1, ROUND(EXTRACT(EPOCH FROM NOW()) * 1000)::bigint)
   ON CONFLICT (namespace) DO NOTHING"]}
